    'RegistrationText'=>'Registrovaným inštanciám SimpleRisk je okamžite udelený prístup k doplnkom Upgrade and Secure Controls Framework (SCF). Upgrade Extra poskytuje možnosť zálohovať a aktualizovať vašu inštanciu SimpleRisk kliknutím na tlačidlo. Secure Controls Framework (SCF) Extra poskytuje spoločný rámec kontroly, ktorý je integrovaný do funkcie SimpleRisk Governance. Po registrácii SimpleRisk budú vaše registračné informácie odoslané na server hostený spoločnosťou SimpleRisk. Poskytnuté registračné informácie použije SimpleRisk na informovanie zákazníkov o nových vydaniach a aktualizáciách zabezpečenia. Akt registrácie SimpleRisk vás prihlási do našej marketingovej komunikácie, ale môžete sa kedykoľvek odhlásiť pomocou odkazu na zrušenie odberu v týchto oznámeniach. SimpleRisk rešpektuje súkromie našich zákazníkov a informácie, ktoré nám poskytnete prostredníctvom procesu registrácie SimpleRisk, nebudú nikdy predané tretej strane.',
